window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e069b0fd4f53acbd"]={"versions": [{"id": "FIG-e069b0fd4f53acbd", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodisches Architektur- und Prozessdiagramm zur Veranschaulichung der AUTOSAR-Template-Methodologie anhand des Beispiels des SystemTemplate. Das Diagramm gliedert sich in drei Ebenen: Spezifikationsdokumente und M2-Metamodell-Templates (oben), Schema-Generierungswerkzeug (Mitte) sowie erzeugte XML-Schema-Artefakte und Instanzdokumente auf M1-Ebene (unten).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten sind nach Artefakttypen typisiert und farblich codiert:</p>\n<ul class=\"fig-list\">\n<li>Spezifikationsdokumente («Text Document»): „Generic Structure Template“, „Requirements on System Template“, „SystemTemplate“ (grün hinterlegt) sowie methodische Regelwerke „UML and the Autosar Template Profile“ und „Model Persistence Rules“ (blau-violett hinterlegt).</li>\n<li>Metamodell: Symbolische Repräsentation „Model M2 Templates“.</li>\n<li>Tool: „Schema Generator“ (als Lineal-/Geometrie-Icon dargestellt).</li>\n<li>XML-Artefakte: «XML Schema» „Data Exchange Format“ (beige hinterlegt) sowie die konkreten Instanzdateien («XML File») „System Configuration Description“ und „System Constraint Description“ (gelb hinterlegt).</li>\n<li>Beziehungen und Schnittstellen:</li>\n<li>„Model M2 Templates“: <code>+is partly described in</code> -> „Generic Structure Template“, <code>+isGovernedBy</code> -> „UML and the Autosar Template Profile“.</li>\n<li>„UML and the Autosar Template Profile“: <code>+is described in</code> -> „Generic Structure Template“.</li>\n<li>„Model Persistence Rules“: <code>specifiesSerialization</code> -> „UML and the Autosar Template Profile“.</li>\n<li>„SystemTemplate“ -> „Requirements on System Template“ (gestrichelter Pfeil, Rückverfolgbarkeit/Anforderungserfüllung).</li>\n<li>„Schema Generator“: verarbeitet „Model M2 Templates“ (durchgehender Pfeil), referenziert/implementiert „SystemTemplate“ und <code>+implements</code> „Model Persistence Rules“ (gestrichelte Pfeile), und <code>+generates</code> das «XML Schema» „Data Exchange Format“ (durchgehender Pfeil).</li>\n<li>«XML File» „System Configuration Description“ und „System Constraint Description“: jeweils <code>+instance of</code> -> «XML Schema» „Data Exchange Format“ (gestrichelte Pfeile).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der methodische Ablauf vollzieht sich von der Definition zur Instanziierung:</p>\n<ol class=\"fig-list\">\n<li>Das M2-Metamodell („Model M2 Templates“) wird durch das AUTOSAR-UML-Template-Profil („UML and the Autosar Template Profile“) reglementiert (<code>+isGovernedBy</code>) und textuell in Spezifikationen wie dem Generic Structure Template („Generic Structure Template“) beschrieben.</li>\n<li>Die Serialisierungsvorgaben für das Metamodell werden durch die Persistenzregeln („Model Persistence Rules“) spezifiziert (<code>specifiesSerialization</code>).</li>\n<li>Der „Schema Generator“ nimmt das M2-Modell entgegen und setzt die in „SystemTemplate“ sowie den „Model Persistence Rules“ festgelegten Regeln um (<code>+implements</code>), um das XML-Schema („Data Exchange Format“) zu generieren (<code>+generates</code>).</li>\n<li>Auf Anwenderebene werden Instanzdateien wie die „System Configuration Description“ und „System Constraint Description“ konform zum generierten XML-Schema instanziiert (<code>+instance of</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Beziehung zwischen Metamodellierung (M2), Persistenzspezifikationen und den daraus abgeleiteten XML-Schemas (M1-Schema). Für Tool- und Schema-Entwickler ist die strikte Trennung zwischen abstrakter M2-Modellierung, Persistenzregeln (Model Persistence Rules) und der automatisierten Schemagenerierung maßgeblich. XML-Dateien (System Configuration Description, System Constraint Description) sind strikte Validierungsinstanzen des generierten Schemas.</p>"}, {"id": "FIG-c60304902873e75b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodisches Architektur- und Prozessdiagramm zur Veranschaulichung der AUTOSAR-Template-Methodologie anhand des Beispiels des SystemTemplate. Das Diagramm gliedert sich in drei Ebenen: Spezifikationsdokumente und M2-Metamodell-Templates (oben), Schema-Generierungswerkzeug (Mitte) sowie erzeugte XML-Schema-Artefakte und Instanzdokumente auf M1-Ebene (unten).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Entitäten sind nach Artefakttypen typisiert und farblich codiert:</p>\n<ul class=\"fig-list\">\n<li>Spezifikationsdokumente («Text Document»): „Generic Structure Template“, „Requirements on System Template“, „SystemTemplate“ (grün hinterlegt) sowie methodische Regelwerke „UML and the Autosar Template Profile“ und „Model Persistence Rules“ (blau-violett hinterlegt).</li>\n<li>Metamodell: Symbolische Repräsentation „Model M2 Templates“.</li>\n<li>Tool: „Schema Generator“ (als Lineal-/Geometrie-Icon dargestellt).</li>\n<li>XML-Artefakte: «XML Schema» „Data Exchange Format“ (beige hinterlegt) sowie die konkreten Instanzdateien («XML File») „System Configuration Description“ und „System Constraint Description“ (gelb hinterlegt).</li>\n<li>Beziehungen und Schnittstellen:</li>\n<li>„Model M2 Templates“: <code>+is partly described in</code> -> „Generic Structure Template“, <code>+isGovernedBy</code> -> „UML and the Autosar Template Profile“.</li>\n<li>„UML and the Autosar Template Profile“: <code>+is described in</code> -> „Generic Structure Template“.</li>\n<li>„Model Persistence Rules“: <code>specifiesSerialization</code> -> „UML and the Autosar Template Profile“.</li>\n<li>„SystemTemplate“ -> „Requirements on System Template“ (gestrichelter Pfeil, Rückverfolgbarkeit/Anforderungserfüllung).</li>\n<li>„Schema Generator“: verarbeitet „Model M2 Templates“ (durchgehender Pfeil), referenziert/implementiert „SystemTemplate“ und <code>+implements</code> „Model Persistence Rules“ (gestrichelte Pfeile), und <code>+generates</code> das «XML Schema» „Data Exchange Format“ (durchgehender Pfeil).</li>\n<li>«XML File» „System Configuration Description“ und „System Constraint Description“: jeweils <code>+instance of</code> -> «XML Schema» „Data Exchange Format“ (gestrichelte Pfeile).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der methodische Ablauf vollzieht sich von der Definition zur Instanziierung:</p>\n<ol class=\"fig-list\">\n<li>Das M2-Metamodell („Model M2 Templates“) wird durch das AUTOSAR-UML-Template-Profil („UML and the Autosar Template Profile“) reglementiert (<code>+isGovernedBy</code>) und textuell in Spezifikationen wie dem Generic Structure Template („Generic Structure Template“) beschrieben.</li>\n<li>Die Serialisierungsvorgaben für das Metamodell werden durch die Persistenzregeln („Model Persistence Rules“) spezifiziert (<code>specifiesSerialization</code>).</li>\n<li>Der „Schema Generator“ nimmt das M2-Modell entgegen und setzt die in „SystemTemplate“ sowie den „Model Persistence Rules“ festgelegten Regeln um (<code>+implements</code>), um das XML-Schema („Data Exchange Format“) zu generieren (<code>+generates</code>).</li>\n<li>Auf Anwenderebene werden Instanzdateien wie die „System Configuration Description“ und „System Constraint Description“ konform zum generierten XML-Schema instanziiert (<code>+instance of</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Beziehung zwischen Metamodellierung (M2), Persistenzspezifikationen und den daraus abgeleiteten XML-Schemas (M1-Schema). Für Tool- und Schema-Entwickler ist die strikte Trennung zwischen abstrakter M2-Modellierung, Persistenzregeln (Model Persistence Rules) und der automatisierten Schemagenerierung maßgeblich. XML-Dateien (System Configuration Description, System Constraint Description) sind strikte Validierungsinstanzen des generierten Schemas.</p>"}], "trans": [{"from": "FIG-e069b0fd4f53acbd", "to": "FIG-c60304902873e75b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
